import { Component } from "simplicit";

import Comment from "models/article/Comment";

// Keeps #comments non-empty (and so visible) when the collection is.
class NoComments extends Component {
  static name = "no-comments";

  static template = ({ any }) =>
    `<p id="no_comments" data-component="no-comments"${any ? " hidden" : ""}>No comments.</p>`;

  connect() {
    const read = () => this.update({ any: Comment.loaded.length > 0 });
    this.registerCleanup(Comment.onChange(read));
    read();
  }
}

export default NoComments;
