import { Component } from "simplicit";

import Comment from "models/article/Comment";

// Not a per-record representation — a collection-level readout, so it watches
// the Model itself instead of being bound to one record.
class CommentsCount extends Component {
  static name = "comments-count";

  static template = ({ count }) => `
    <a id="comments_count" href="#comments" data-component="comments-count"
      >${count} comment${count === 1 ? "" : "s"}</a
    >`;

  connect() {
    const read = () => this.update({ count: Comment.loaded.length });
    this.registerCleanup(Comment.onChange(read));
    read();
  }
}

export default CommentsCount;
