import LocoReactive from "models/LocoReactive";
import MainComment from "components/main/Comment";

class Comment extends LocoReactive {
  static name = "Comment";

  // Explicit: the identity is namespaced, so it can't be derived from `name`.
  static identity = "Article.Comment";

  static components = [MainComment];

  static remoteName = "Comment";

  static resources = {
    url: "/user/articles/:articleId/comments",
    paginate: { per: 10 },
    main: {
      url: "/articles/:articleId/comments",
      paginate: { per: 5, param: "page-num" },
    },
    admin: {
      url: "/admin/articles/:articleId/comments",
      paginate: { per: 5 },
    },
  };

  static attributes = {
    author: {
      validations: {
        presence: true,
      },
    },
    text: {
      validations: {
        presence: true,
        vulgarity: true,
      },
    },
    articleId: {
      type: "Int",
      validations: {
        presence: true,
      },
      remoteName: "article_id",
    },
    createdAt: {
      type: "Date",
      remoteName: "created_at",
    },
    updatedAt: {
      type: "Date",
      remoteName: "updated_at",
    },
    emotion: {
      type: "Int",
    },
    pinned: {
      type: "Boolean",
    },
    adminRate: {
      type: "Int",
      remoteName: "admin_rate",
    },
    approved: {
      type: "Boolean",
    },
  };
}

export default Comment;
